from taf.cloud.ncir.ncir import Ncir
from taf.cloud.ncir.session import Session17A
from taf.cloud.ncir import exception

import json


class Ncir17A(Ncir):
    SYSINV_PORT = '6385'

    def __init__(self):
        self._session = None

    def connect(self, address, username='admin', password='uteadmin', verify=False):
        self._session = Session17A(address, verify)
        response = self._session.authenticate(username, password)
        self._check_response(response)
        self._session.auth_token = response.headers['X-Subject-Token']

    def _check_response(self, response):
        resp_json = response.json()
        if resp_json is not None:
            err_msg = resp_json.get('error_message', None)
            exception_message = err_msg if err_msg else json.dumps(resp_json)
        else:
            exception_message = None
        self._verify_response_code(response, exception_message)

    @staticmethod
    def _get_code_exception(resp):
        codes_exceptions = {400: exception.BadRequest, 401: exception.Unauthorized,
                            403: exception.Forbidden, 405: exception.BadMethod,
                            413: exception.OverLimit, 404: exception.ItemNotFound,
                            503: exception.BadRequest}
        ncir_exception = codes_exceptions.get(resp.status_code, None)
        return ncir_exception

    def _verify_response_code(self, response, exception_message):
        ncir_exception = self._get_code_exception(response)
        if ncir_exception is not None:
            raise ncir_exception(exception_message)

    def get_host_id_by_name(self, host_name):
        endpoint = 'v1/ihosts'
        response = self._session.send_request('get', endpoint, self.SYSINV_PORT)
        self._check_response(response)
        for ihost in response.json()['ihosts']:
            if ihost['hostname'] == host_name:
                return ihost['id']
        raise exception.HostNotFound("Host with hostname {} not found.".format(host_name))

    def _action_host(self, action, host_id):
        endpoint = 'v1/ihosts/{host_id}'.format(host_id=host_id)
        body = [{'path': '/action', 'value': action, 'op': 'replace'}]
        headers = {'Content-Type': 'application/json'}
        response = self._session.send_request(method='patch', endpoint=endpoint, port=self.SYSINV_PORT,
                                              headers=headers, data=json.dumps(body))
        self._check_response(response)
        return response.json()

    def lock_host(self, host_id):
        self._action_host('lock', host_id)

    def unlock_host(self, host_id):
        self._action_host('unlock', host_id)

    def force_lock_host(self, host_id):
        self._action_host('force-lock', host_id)

    def swact_host(self, host_id):
        self._action_host('swact', host_id)
